  stucco_wall(g, hx0, 9, hx0, 9, 2, 4);
  stucco_wall(g, hx0, 10, hx0, 10, 4, 4);
  stucco_wall(g, hx0, 11, hx0, 13, 2, 4);
  stucco_wall(g, hx0, 14, hx0, 16, 2, 2);
  stucco_wall(g, hx0, 17, hx0, 24, 2, 4);
