  stucco_wall(g, hx1, 9, hx1, 9, 2, 4);
  stucco_wall(g, hx1, 10, hx1, 12, 2, 2);
  stucco_wall(g, hx1, 13, hx1, 14, 2, 4);
  stucco_wall(g, hx1, 15, hx1, 16, 2, 3);
  stucco_wall(g, hx1, 17, hx1, 20, 2, 4);
