function ceiling(g) {
  for (const [za, zb] of [[9, 13], [20, 24]]) for (let x = 11; x <= 30; x++) for (let z = za; z <= zb; z++) {
    if (isBeam(x) || inAtrium(x, z) || inChimney(x, z)) continue;
